// === 1. TCC：库存预占，处理空回滚、悬挂和幂等 ===
@Service
public class InventoryTccService {

    @Transactional
    public boolean tryDeduct(String xid, String branchId, String skuId, int quantity) {
        // 幂等 + 悬挂防护：已存在记录时按状态决定行为
        TccBranch branch = branchRepo.find(xid, branchId);
        if (branch != null && branch.isCancelled()) {
            // Cancel 已先执行（空回滚），迟到的 Try 必须拒绝，否则造成悬挂
            return false;
        }
        if (branch != null && branch.isTried()) {
            return true; // 幂等返回
        }

        // 正常 Try：冻结资源
        Inventory inv = inventoryRepo.selectForUpdate(skuId);
        if (inv.getAvailable() < quantity) return false;
        inv.setAvailable(inv.getAvailable() - quantity);
        inv.setFrozen(inv.getFrozen() + quantity);
        inventoryRepo.update(inv);
        branchRepo.insert(xid, branchId, skuId, quantity, BranchStatus.TRIED);
        return true;
    }

    @Transactional
    public void confirmDeduct(String xid, String branchId) {
        TccBranch branch = branchRepo.findForUpdate(xid, branchId);
        if (branch == null || branch.isConfirmed()) return; // 幂等
        if (branch.isCancelled()) return; // 异常状态保护

        // 消耗冻结资源
        Inventory inv = inventoryRepo.selectForUpdate(branch.getSkuId());
        inv.setFrozen(inv.getFrozen() - branch.getQuantity());
        inventoryRepo.update(inv);
        branchRepo.markStatus(xid, branchId, BranchStatus.CONFIRMED);
    }

    @Transactional
    public void cancelDeduct(String xid, String branchId, String skuId, int quantity) {
        TccBranch branch = branchRepo.findForUpdate(xid, branchId);
        if (branch == null) {
            // 空回滚：Try 从未执行，插入 CANCELLED 标记防止迟到 Try 悬挂
            branchRepo.insert(xid, branchId, skuId, quantity, BranchStatus.CANCELLED);
            return;
        }
        if (branch.isCancelled() || branch.isConfirmed()) return; // 幂等

        // 释放冻结资源
        Inventory inv = inventoryRepo.selectForUpdate(branch.getSkuId());
        inv.setFrozen(inv.getFrozen() - branch.getQuantity());
        inv.setAvailable(inv.getAvailable() + branch.getQuantity());
        inventoryRepo.update(inv);
        branchRepo.markStatus(xid, branchId, BranchStatus.CANCELLED);
    }
}

// === 2. 本地消息表：业务与 outbox 同库提交，可靠投递 ===
@Service
public class OrderService {
    @Transactional
    public OrderId createOrder(CreateOrderCmd cmd) {
        Order order = Order.create(cmd);
        orderRepo.save(order);
        // 业务写入和消息记录在同一个本地事务，保证原子性
        LocalMessage msg = LocalMessage.pending(
            UUID.randomUUID().toString(),
            "order-created",
            order.getId().toString(),
            JSON.toJSONString(order)
        );
        localMessageRepo.save(msg);
        return order.getId();
    }
}

// 后台轮询投递
@Scheduled(fixedDelay = 1000)
public void pollAndSend() {
    List<LocalMessage> messages = localMessageRepo.lockPending(100);
    for (LocalMessage msg : messages) {
        try {
            kafkaTemplate.send(msg.getTopic(), msg.getBizKey(), msg.getPayload()).get();
            msg.markSent();
        } catch (Exception e) {
            msg.increaseRetry();
            if (msg.getRetryCount() >= MAX_RETRY) msg.markDead(); // 死信
        }
        localMessageRepo.update(msg);
    }
}
